examples.code:
Box(
    modifier = Modifier.onPreviewKeyEvent { event ->
        val toggle = event.type == KeyEventType.KeyDown && event.isCtrlPressed && event.key == Key.J
        if (toggle) open = !open
        toggle
    },
) {
    MonarchAiLauncher(
        open = open,
        onOpenChange = { open = it },
        icon = { MonarchIcon(SampleIcons.Bot, contentDescription = null) },
    )
}
